const nested = generatePerlBindingPackage({ ...base, types: [nat, text, digits].map(keyed), exports: [odd] }, receipt)["Component.xs"];
const start = nested.indexOf("\nodd(...)"), finish = nested.indexOf("XSRETURN(1);", start);
